+void radix_sort_pass(const uint32_t* src, uint32_t* dst, size_t n, uint32_t shift, const uint32_t* hist) {
+    uint32_t offsets[256];
+    offsets[0] = 0;
+    for (int i = 1; i < 256; ++i) {
+        offsets[i] = offsets[i - 1] + hist[(i - 1) + (shift == 0 ? 0 : shift == 8 ? 256 : shift == 16 ? 512 : 768)];
