+        uint8x16_t b0_1 = vqtbl1q_u8(v1, mask_b0);
+        uint8x16_t b0_2 = vqtbl1q_u8(v2, mask_b0);
+        uint8x16_t b0_3 = vqtbl1q_u8(v3, mask_b0);
