+        vst1q_u8(buf, b0_1);
+        for (int k = 0; k < 16; ++k) ++hist[buf[k]];
+        vst1q_u8(buf, b0_2);
+        for (int k = 0; k < 16; ++k) ++hist[buf[k]];
+        vst1q_u8(buf, b0_3);
+        for (int k = 0; k < 16; ++k) ++hist[buf[k]];
+
+        // Extract byte 1 from all 4 vectors
