+void lsd_radix_sort(uint32_t* a, size_t n, uint32_t* tmp) {
+    if (n < INSERTION_SORT_THRESHOLD) {
+        insertion_sort(a, n);
+        return;
+    }
+    
+    // Check if already sorted
+    if (is_sorted(a, n)) return;
+    
+    // Single counting pass for all 4 bytes
+    uint32_t hist[1024] = {0};
+    
+#if defined(__ARM_NEON) || defined(__aarch64__)
+    count_bytes_neon(a, n, hist);
+#else
+    count_bytes_scalar(a, n, hist);
+#endif
