+    // Check if we can skip any passes (all elements have same byte value)
+    bool skip_pass[4] = {false};
+    for (int pass = 0; pass < 4; ++pass) {
+        uint32_t base = pass * 256;
+        uint32_t count = hist[base];
+        if (count == n) {
+            skip_pass[pass] = true;
+        }
+    }
+    
+    uint32_t* src = a;
+    uint32_t* dst = tmp;
+    
+    for (int pass = 0; pass < 4; ++pass) {
+        if (skip_pass[pass]) continue;
+        
+        radix_sort_pass(src, dst, n, pass * 8, hist);
+        std::swap(src, dst);
+    }
+    
+    // If final result is in tmp, copy back to a
+    if (src != a) {
+        std::copy(tmp, tmp + n, a);
+    }
+}
